    size_t i;
    adcs_status_t st;
    adcs_vec3_t h, tq;
    double e;

    if ((wheels == NULL) || (field == NULL) || (momentum == NULL) || (command == NULL) ||
        (torque == NULL) || (energy == NULL) || (dissipation == NULL)) {
        if (momentum != NULL) *momentum = (adcs_vec3_t){0, 0, 0};
        if (command != NULL) { command->command = (adcs_vec3_t){0, 0, 0}; command->saturated_axes = 0U; }
        if (torque != NULL) *torque = (adcs_vec3_t){0, 0, 0};
        if (energy != NULL) *energy = 0.0;
        if (dissipation != NULL) *dissipation = 0.0;
        return ADCS_E_NULL;
    }

    *momentum = (adcs_vec3_t){0, 0, 0};
    command->command = (adcs_vec3_t){0, 0, 0};
    command->saturated_axes = 0U;
    *torque = (adcs_vec3_t){0, 0, 0};
    *energy = 0.0;
    *dissipation = 0.0;

    if ((count < 1U) || (count > 16U) || (!adcs_is_finite_vec3(field)))
        return ADCS_E_RANGE;

    for (i = 0; i < count; i++) {
        if ((!isfinite(wheels[i].inertia_kg_m2)) || (wheels[i].inertia_kg_m2 <= 0.0) ||
            (!isfinite(wheels[i].speed_rad_s)))
            return ADCS_E_RANGE;
    }

    st = adcs_wheel_momentum(wheels, count, &h);
    if (st != ADCS_OK)
        return ADCS_E_RANGE;

    *momentum = h;

    e = 0.0;
    for (i = 0; i < count; i++)
        e += 0.5 * wheels[i].inertia_kg_m2 * wheels[i].speed_rad_s * wheels[i].speed_rad_s;
    *energy = e;

    st = adcs_momentum_unload_dipole(momentum, field, gain, dipole_limit, command, &tq);
    if (st != ADCS_OK) {
        *momentum = (adcs_vec3_t){0, 0, 0};
        command->command = (adcs_vec3_t){0, 0, 0};
        command->saturated_axes = 0U;
        *torque = (adcs_vec3_t){0, 0, 0};
        *energy = 0.0;
        *dissipation = 0.0;
        return st;
    }

    *torque = tq;
    *dissipation = adcs_vec3_dot(momentum, torque);

    return ADCS_OK;
}

